(()=>{'use strict';const $=(s,r=document)=>r.querySelector(s),$$=(s,r=document)=>[...r.querySelectorAll(s)];
window.addEventListener('click',e=>{const button=e.target.closest('button');if(window.DEMO_PAGE?.id!=='BL-02-02'||button?.textContent.trim()!=='查看需求')return;e.preventDefault();e.stopImmediatePropagation();const row=button.closest('.kodo-art-table-row'),table=row?.closest('.kodo-art-table'),head=table&&$('.kodo-art-table-thead .kodo-art-table-row',table);if(!row||!head){window.DEMO_CONTEXT.toast('未取得当前明细，无法查看关联需求');return;}const labels=[...head.children].map(e=>e.textContent.trim()),at=labels.indexOf('订单编号'),code=at>=0?row.children[at]?.textContent.trim():'';if(!/^DEMO-[A-Za-z0-9-]+$/.test(code)){window.DEMO_CONTEXT.toast('此明细没有可核对的本地订单编号');return;}location.href='BL-02-03.html?from=salesDetail&order='+encodeURIComponent(code);},true);
window.addEventListener('DOMContentLoaded',()=>{if(window.DEMO_PAGE?.id==='BL-02-03'){const params=new URLSearchParams(location.search),code=params.get('order');if(params.get('from')==='salesDetail'&&!params.has('detail')&&/^DEMO-[A-Za-z0-9-]+$/.test(code||'')){const input=$$('input').find(e=>e.placeholder==='请输入订单编号');if(input){input.value=code;input.dispatchEvent(new Event('input',{bubbles:true}));const query=$$('button').find(e=>e.textContent.replace(/\s/g,'').replace(/^\d+/,'')==='查询');query?.click();}else window.DEMO_CONTEXT.toast('未找到订单筛选控件，关联筛选未应用');}}});
})();
